* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Inter",
    Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

p { margin: 0 0 1em; }
p:last-child { margin-bottom: 0; }

.container {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 12px;
  top: -40px;
  padding: 8px 14px;
  background: var(--text);
  color: #fff;
  border-radius: 8px;
  text-decoration: none;
  font-weight: 600;
  z-index: 100;
}
.skip-link:focus {
  top: 12px;
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

/* Header */
.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.brand {
  margin: 0;
  padding: 18px 0;
  font-weight: 700;
  font-size: 1.05rem;
  letter-spacing: 0.2px;
}

/* Hero */
.hero {
  padding: 56px 0 24px;
}
.hero h1 {
  margin: 0 0 12px;
  font-size: clamp(2rem, 4vw + 1rem, 3rem);
  line-height: 1.15;
  letter-spacing: -0.02em;
}
.lede {
  font-size: 1.125rem;
  color: var(--text-muted);
  max-width: 56ch;
}

/* FAQ */
.faq {
  padding: 24px 0 64px;
}
.faq h2 {
  margin: 0 0 20px;
  font-size: 1.25rem;
  letter-spacing: -0.01em;
}

.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-bottom: 12px;
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  transition: box-shadow 160ms ease, border-color 160ms ease;
}
.example:hover { box-shadow: var(--shadow-md); }
.example:focus-within { border-color: var(--accent); }

.example h3 {
  margin: 0;
  font-size: 1rem;
}

.faq-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px;
  background: transparent;
  border: 0;
  text-align: left;
  font: inherit;
  font-weight: 600;
  font-size: 1.0625rem;
  color: var(--text);
  cursor: pointer;
  border-radius: var(--radius);
}

.faq-trigger:hover .faq-trigger-text {
  color: var(--accent);
}

.faq-trigger:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}

.faq-icon {
  flex: 0 0 auto;
  width: 14px;
  height: 14px;
  position: relative;
  transition: transform 200ms ease;
}
.faq-icon::before,
.faq-icon::after {
  content: "";
  position: absolute;
  inset: 0;
  margin: auto;
  background: currentColor;
  border-radius: 2px;
}
.faq-icon::before {
  width: 14px;
  height: 2px;
}
.faq-icon::after {
  width: 2px;
  height: 14px;
  transition: transform 200ms ease, opacity 200ms ease;
}
.faq-trigger[aria-expanded="true"] .faq-icon::after {
  transform: rotate(90deg);
  opacity: 0;
}

.details {
  padding: 0 20px 20px;
  color: var(--text-muted);
  font-size: 1rem;
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--border);
  background: var(--surface);
}
.site-footer p {
  padding: 20px 0;
  color: var(--text-muted);
  font-size: 0.9rem;
  text-align: center;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}

/* Forced colors / high contrast */
@media (forced-colors: active) {
  .example { border: 1px solid CanvasText; }
  .faq-trigger:focus-visible { outline-color: Highlight; }
  .faq-icon::before, .faq-icon::after { background: CanvasText; }
}

/* Dark mode */
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #131316;
    --surface: #1c1c20;
    --border: #2c2c33;
    --text: #f3f3f3;
    --text-muted: #b4b4b8;
    --accent: #a594ff;
    --accent-hover: #b8a9ff;
    --focus: #8ab4ff;
    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.4);
    --shadow-md: 0 4px 16px rgba(0, 0, 0, 0.4);
  }
}
